using System;
using System.Reflection;
using System.IO;
using System.Text;
namespace PZ3D {
 static class LaunchProfilesTests {
  static void Check(bool value,string label){Console.WriteLine((value?"PASS: ":"FAIL: ")+label);if(!value)throw new Exception(label);}
  public static void Run(){var type=typeof(Engine).Assembly.GetType("PZ3D.LaunchProfiles");Check(type!=null,"session launch isolates local mods without destroying original configuration");
   string original="VERSION = 1,\nmods\n{\n mod = Regular,\n mod = Viewpoint,\n mod = ZombieBuddy,\n}\nmaps\n{\n map = LocalMap,\n}\ncustom\n{\n keep = yes,\n}\n";
   string next=LaunchProfiles.BuildDefault(original,"server",new[]{"ZombieBuddy","Viewpoint"});Check(!next.Contains("Regular")&&!next.Contains("LocalMap")&&next.Contains("Viewpoint")&&next.Contains("custom"),"server launch excludes ordinary mods/maps and preserves exact verified extensions and unknown blocks");
   string root=Path.Combine(LauncherTestPaths.Root,"orange-launch-test-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);Directory.CreateDirectory(Path.GetDirectoryName(e.Mods));File.WriteAllText(e.Mods,original,new UTF8Encoding(true));byte[] before=File.ReadAllBytes(e.Mods);
   Directory.CreateDirectory(e.Game);File.WriteAllText(e.Config,"{\"vmArgs\":[]}");LaunchProfiles.Stage(e,new ProfileLaunchRequest{Kind="server",Id="fixture",Host="127.0.0.1",Port=16261,Username="player",UserPassword="role-secret",ServerPassword="server-secret"});Check(LaunchProfiles.Pending(e)&&!File.ReadAllText(e.Mods).Contains("Regular"),"temporary multiplayer profile staged with durable recovery record");
   string request=Path.Combine(e.User,"OrangeLauncherSession.request");Check(File.ReadAllText(request).Contains("role-secret")&&File.ReadAllText(request).Contains("server-secret"),"independent server and character passwords reach private one-shot request");
   string journal=Directory.GetFiles(Path.Combine(e.Data,"launch-sessions"))[0];Check(!File.ReadAllText(journal).Contains("secret"),"recovery record never contains login secrets");
   var serializer=new System.Web.Script.Serialization.JavaScriptSerializer();var record=serializer.Deserialize<ProfileSessionRecord>(File.ReadAllText(journal));record.CreatedUtc="2000-01-01T00:00:00Z";File.WriteAllText(journal,serializer.Serialize(record));string applied=File.ReadAllText(e.Mods);LaunchProfiles.State(e);Check(File.ReadAllText(e.Mods)==applied&&File.Exists(journal)&&File.Exists(request),"read-only status never restores files or deletes a pending launch request");
   var oldRecord=serializer.Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(journal));string oldNonce=oldRecord.ContainsKey("Nonce")?(string)oldRecord["Nonce"]:"old-session";var expire=typeof(LaunchProfiles).GetMethod("ExpireRequest");Check(expire!=null,"background watchdog can expire private credentials before game exits");expire.Invoke(null,new object[]{e,oldNonce});Check(!File.Exists(request)&&LaunchProfiles.Pending(e)&&File.ReadAllText(e.Mods)==applied,"expired private request scrub preserves running session configuration");LaunchProfiles.Recover(e,true);Check(Convert.ToBase64String(File.ReadAllBytes(e.Mods))==Convert.ToBase64String(before)&&!LaunchProfiles.Pending(e)&&!File.Exists(request),"normal exit recovery restores original exact BOM bytes and removes sensitive request");
   LaunchProfiles.Stage(e,new ProfileLaunchRequest{Kind="save",Id="Sandbox/A",Mode="Sandbox",Save="A"});string newer=File.ReadAllText(e.Mods);var recover=typeof(LaunchProfiles).GetMethod("Recover");recover.Invoke(null,recover.GetParameters().Length==3?new object[]{e,true,oldNonce}:new object[]{e,true});Check(LaunchProfiles.Pending(e)&&File.ReadAllText(e.Mods)==newer,"stale game-exit watcher cannot restore a newer prepared session");LaunchProfiles.Recover(e,true);
   File.WriteAllText(e.Config,"{\"vmArgs\":[\"-agentlib:zbNative\"]}");File.WriteAllText(System.IO.Path.Combine(e.Game,"ZombieBuddy.jar"),"fixture");File.WriteAllText(System.IO.Path.Combine(e.Game,"zbNative.dll"),"fixture");File.AppendAllText(e.Mods,"\nmod = OrangeShootPresentation,\n");string addon=System.IO.Path.Combine(e.User,"mods","OrangeShootPresentation","42");Directory.CreateDirectory(System.IO.Path.Combine(addon,"media","java","client"));File.WriteAllText(System.IO.Path.Combine(addon,"mod.info"),"id=OrangeShootPresentation\njavaPkgName=orange.ads\njavaJarFile=media/java/client/OrangeShootPresentation.jar\n");File.WriteAllText(System.IO.Path.Combine(addon,"media","java","client","OrangeShootPresentation.jar"),"owned");File.WriteAllText(PresentationBridge.PropertiesPath(e),"owned");var bridge=new PresentationBridge();string bridgeJournal=(string)typeof(PresentationBridge).GetMethod("Journal",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(bridge,new object[]{e});File.WriteAllText(bridgeJournal,"{\"addon\":\"2\"}");string[] retained=(string[])typeof(LaunchProfiles).GetMethod("Retained",BindingFlags.NonPublic|BindingFlags.Static,null,new[]{typeof(Engine)},null).Invoke(null,new object[]{e});Check(Array.IndexOf(retained,PresentationBridge.Id)>=0,"server launch retains enabled managed reticle fallback extension as well as authors components");File.WriteAllBytes(e.Mods,before);
   LaunchProfiles.Stage(e,new ProfileLaunchRequest{Kind="save",Id="Sandbox/A",Mode="Sandbox",Save="A"});File.AppendAllText(e.Mods,"\nexternal edit\n");string external=File.ReadAllText(e.Mods);LaunchProfiles.Recover(e,true);Check(File.ReadAllText(e.Mods)==external&&LaunchProfiles.Pending(e)&&!File.Exists(request),"external edit prevents recovery overwrite and still scrubs credentials");
   var bad=new Engine(Path.Combine(root,"game2"),Path.Combine(root,"user2"),Path.Combine(root,"data2"),true);bool refused=false;try{LaunchProfiles.Stage(bad,new ProfileLaunchRequest{Kind="save",Id="bad",Mode="Sandbox",Save="../escape"});}catch{refused=true;}Check(refused&&!LaunchProfiles.Pending(bad),"invalid target rejected before staging any files");
   Directory.CreateDirectory(bad.Game);File.WriteAllText(bad.Config,"{\"vmArgs\":[]}");LaunchProfiles.Stage(bad,new ProfileLaunchRequest{Kind="server",Host="127.0.0.1",Port=16261,Username="p"});LaunchProfiles.Recover(bad,true);Check(!File.Exists(bad.Mods)&&!LaunchProfiles.Pending(bad),"missing original default file remains absent after session recovery");
   LaunchProfiles.Stage(bad,new ProfileLaunchRequest{Kind="server",Host="127.0.0.1",Port=16261,Username="p"});string malformedJournal=Directory.GetFiles(Path.Combine(bad.Data,"launch-sessions"))[0],good=File.ReadAllText(malformedJournal);var malformed=serializer.Deserialize<ProfileSessionRecord>(good);malformed.Files[Path.Combine(root,"foreign.txt")]=new string('A',64);File.WriteAllText(malformedJournal,serializer.Serialize(malformed));string keepApplied=File.ReadAllText(bad.Mods);refused=false;try{LaunchProfiles.Recover(bad,true);}catch{refused=true;}Check(refused&&File.Exists(bad.Mods)&&File.ReadAllText(bad.Mods)==keepApplied&&LaunchProfiles.Pending(bad),"malformed ownership record refuses before altering current default mods");File.WriteAllText(malformedJournal,good);LaunchProfiles.Recover(bad,true);
  }
  public static int Main(){try{Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
